package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Integer;
    in attribute io_1 : Real;
    in attribute io_2 : Boolean;
    attribute accumulatedMs : Integer := 0;
    attribute lastValidTemp : Real := 0.0;
    perform action tick {
      first start;
      then if io_2 {
        first start;
        then assign lastValidTemp := io_1;
      }
      then assign accumulatedMs := accumulatedMs + io_0;
      then if accumulatedMs >= 5000 {
        first start;
        then assign accumulatedMs := accumulatedMs - 5000;
      }
    }
    out attribute serial_0_trigger : Boolean = accumulatedMs >= 5000;
    out attribute serial_0_value_0 : Real = (if io_2 ? io_1 else lastValidTemp);
  }
  part system : Controller;
}
